def main():
    assert len(P) == 20, f"断言例数 {len(P)} != 20"
    total = 0
    written = 0
    for cid in IDS:
        rec = {"case_id": cid,
               "prediction_text": P[cid]["prediction_text"],
               "basis": P[cid]["basis"],
               "confidence": P[cid]["confidence"],
               "trigger": P[cid]["trigger"]}
        path = os.path.join(OUT, cid + ".json")
        with open(path, "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
        written += 1
    # 逐件自验：精确打开本批文件
    cm = ru = di = 0
    for cid in IDS:
        path = os.path.join(OUT, cid + ".json")
        data = open(path, "rb").read()
        total += len(data)
        obj = json.loads(data.decode("utf-8"))
        assert obj["case_id"] == cid, cid
        for k in ("prediction_text", "basis", "confidence", "trigger"):
            assert k in obj, (cid, k)
        t = obj["trigger"]
        for k in ("changed_main", "reserve_used", "disputed", "reason"):
            assert k in t, (cid, k)
        assert 0.0 <= obj["confidence"] <= 1.0
        cm += bool(t["changed_main"]); ru += bool(t["reserve_used"]); di += bool(t["disputed"])
    print(f"cases={len(IDS)} written={written} bytes={total}")
    print(f"trigger_counts changed_main={cm} reserve_used={ru} disputed={di}")

if __name__ == "__main__":
    main()
